PRAGMA foreign_keys=ON;
CREATE TABLE admin_audit(operation_id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,object_id TEXT NOT NULL,fingerprint TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX audit_date ON admin_audit(created_at DESC);
CREATE TABLE admin_guard(passed INTEGER NOT NULL);
CREATE TRIGGER admin_guard_check BEFORE INSERT ON admin_guard WHEN NEW.passed!=1 BEGIN SELECT RAISE(ABORT,'REVISION_CONFLICT'); END;
CREATE TABLE admin_principals(email TEXT PRIMARY KEY,role TEXT NOT NULL CHECK(role='admin'),created_at TEXT NOT NULL);
INSERT INTO admin_principals VALUES('himentpear@gmail.com','admin',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE drafts(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('textbook','dictionary','grammar','question')),title TEXT NOT NULL,source_version TEXT NOT NULL,document_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',validation_json TEXT,validated_revision INTEGER,created_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE releases(id TEXT PRIMARY KEY,content_version TEXT NOT NULL,dictionary_version TEXT NOT NULL,content_manifest TEXT NOT NULL,dictionary_manifest TEXT NOT NULL,source_commit TEXT,resource_hash TEXT NOT NULL,created_at TEXT NOT NULL,task_id TEXT,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE active_release(slot INTEGER PRIMARY KEY CHECK(slot=1),release_id TEXT NOT NULL REFERENCES releases(id),revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tasks(id TEXT PRIMARY KEY,operation_id TEXT UNIQUE NOT NULL,actor TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,step TEXT NOT NULL,payload_json TEXT NOT NULL,source_commit TEXT,pr_url TEXT,error_code TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE resources(key TEXT PRIMARY KEY,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,content_type TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE resource_refs(release_id TEXT NOT NULL REFERENCES releases(id),resource_key TEXT NOT NULL,PRIMARY KEY(release_id,resource_key));
CREATE TABLE controls(name TEXT PRIMARY KEY,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
INSERT INTO controls VALUES('conversation',1,0,strftime('%Y-%m-%dT%H:%M:%fZ','now')),('transcription',1,0,strftime('%Y-%m-%dT%H:%M:%fZ','now')),('synthesis',1,0,strftime('%Y-%m-%dT%H:%M:%fZ','now')),('correction',1,0,strftime('%Y-%m-%dT%H:%M:%fZ','now')),('live',0,0,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE model_events(id TEXT PRIMARY KEY,model TEXT NOT NULL,feature TEXT NOT NULL,account_hash TEXT,elapsed_ms INTEGER NOT NULL,result TEXT NOT NULL,input_units REAL,output_units REAL,unit TEXT,fallback_reason TEXT,occurred_at TEXT NOT NULL);
CREATE INDEX model_events_date ON model_events(occurred_at);
CREATE TABLE model_daily(day TEXT NOT NULL,model TEXT NOT NULL,feature TEXT NOT NULL,calls INTEGER NOT NULL,failures INTEGER NOT NULL,elapsed_ms INTEGER NOT NULL,estimated_usd REAL,unknown_cost INTEGER NOT NULL,PRIMARY KEY(day,model,feature));
CREATE TABLE rates(id TEXT PRIMARY KEY,model TEXT NOT NULL,unit TEXT NOT NULL,input_per_million REAL NOT NULL,output_per_million REAL NOT NULL,effective_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,UNIQUE(model,unit,effective_at));
